{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Pense no cone pequeno, que vai do vértice (a ponta) até o plano de corte. Ele tem o mesmo formato do cone inteiro, só que menor: é semelhante. Se as medidas de comprimento (raio, altura) do pequeno são k vezes as do grande, as áreas ficam k² vezes e os volumes k³ vezes. A região pedida é o cone inteiro menos o cone pequeno.",
   "motivo": "Explica 'vértice' e 'semelhante' em palavras simples e evita frase com dois sentidos."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["k", "razão de semelhança: medida do cone pequeno ÷ medida correspondente do cone grande"],
    ["semelhante", "mesmo formato, tamanhos diferentes: todas as medidas de comprimento crescem na mesma proporção"],
    ["secção", "círculo que o plano de corte forma dentro do cone"],
    ["vértice", "a ponta do cone, o ponto V da figura"],
    ["razão", "resultado da divisão de uma medida pela outra"],
    ["V", "volume do cone inteiro"]
   ],
   "motivo": "Termos como semelhante, vértice e razão não estavam explicados."
  },
  {
   "campo": "resolucao.pista",
   "depois": "A área dá primeiro a razão entre os raios (uma medida de comprimento). O volume usa essa razão com outro expoente. No fim, pense no que sobra ao tirar o cone de cima.",
   "motivo": "Mais clara, sem entregar a resposta."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "A secção é a base do cone pequeno. Como o cone pequeno é semelhante ao grande, a razão entre as áreas das bases é k². O enunciado diz que essa razão é 36%.",
   "motivo": "Liga o dado do enunciado ao k²."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "A raiz quadrada desfaz o quadrado: de k² sai k. Esse k vale para raio e altura. Confira: 0,6 × 0,6 = 0,36.",
   "motivo": "Evita 'obtém-se' e acrescenta conferência simples."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "A região entre o plano de corte e a base é o cone inteiro sem o cone de cima. Com o total igual a 1 (100%), basta subtrair.",
   "motivo": "Deixa claro que o total vale 1."
  },
  {
   "campo": "resolucao.checagem",
   "depois": "Use um cone de raio 10 e altura 10. O cone menor tem raio 6 e altura 6 (k = 0,6). Os volumes são proporcionais a 10³ = 1000 e 6³ = 216. Então 216 ÷ 1000 = 21,6% e 100% − 21,6% = 78,4%. Fecha.",
   "motivo": "Texto sem fração escrita na linha e com a ideia dos cubos explícita."
  },
  {
   "campo": "resolucao.quadro",
   "depois": [
    {"linha": "k² = 36% = 0,36", "nota": "razão entre as áreas das bases"},
    {"linha": "k = √0,36", "nota": "raiz quadrada desfaz o quadrado"},
    {"linha": "k = 0,6", "nota": "razão entre raios e alturas", "destaque": "0,6"},
    {"linha": "k³ = 0,6 × 0,6 × 0,6", "nota": "razão entre os volumes"},
    {"linha": "0,6 × 0,6 = 0,36", "nota": "primeiro produto"},
    {"linha": "0,36 × 0,6 = 0,216", "nota": "cone menor: 21,6% do total"},
    {"linha": "1 − 0,216 = 0,784", "nota": "total menos o cone menor", "mov": [{"termo": "0,216", "de": "cone menor", "para": "subtração", "vira": "− 0,216", "como": "é retirado do total"}]},
    {"linha": "0,784 = 78,4%", "nota": "região entre os planos", "destaque": "78,4%"}
   ],
   "motivo": "Um passo por linha, sem pular a multiplicação 0,6³."
  }
 ],
